INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-gift', '谢谢生命中遇见的每一份礼物。', '华研国际／《礼物》世界巡回演唱会官宣', 2026, 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-gift', '巡演', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-gift', '礼物', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-arena', '我是曾沛慈，我一直都很喜欢唱歌，但这次，我可以在体育馆唱歌给你们听了，喔耶！', '曾沛慈微博，官宣《礼物》巡演', 2026, 1);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-arena', '巡演', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-arena', '心愿', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-wish', '站在很大的舞台唱歌是我很久之前在内心默默许下的愿望，随着时间过去，我渐渐放下这个目标，久到我几乎忘记这个愿望。不是它不重要，是我知道我不再需要为了证明自己而唱，只要能唱歌，其实在什么舞台唱我都会一样认真面对。', '曾沛慈微博，官宣《礼物》巡演', 2026, 2);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-wish', '舞台', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-wish', '初心', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-waited', '开万人演唱会是自己一直以来的愿望，但时间久到我都快忘记这个愿望了，今天看到官宣的时候就想，我真的等到这一天了。', '《礼物》巡演北京发布会', 2026, 3);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-waited', '巡演', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-waited', '发布会', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-im-pets', '我是曾沛慈。我热爱歌唱，我勇敢踏上我的音乐路。', '首张专辑《我是曾沛慈 I''m Pets》宣传', 2014, 4);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-im-pets', '专辑', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-im-pets', '出道', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-second', '就算成为你第一名的好朋友，却永远只是第二名的情人。', '《我是曾沛慈 I''m Pets》专辑前导预告', 2014, 5);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-second', '专辑', 0);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-ticc-nervous', '这场演唱会我真的很紧张，因为是我很看重、很在乎的演出，所以对自己要求特别高，我每天都练唱到半夜，希望可以给你们看到最好的一面。', '《谜之音》演唱会，台北国际会议中心', 2019, 6);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-ticc-nervous', '演唱会', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-ticc-nervous', '谜之音', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-tight', '这应该是我有史以来穿最贴身的一次，超级贴。', '《谜之音》演唱会开场', 2019, 7);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-tight', '演唱会', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-tight', '现场', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-infinite', '礼物是有形的载体，但承载的陪伴与热爱是无限的。「圆」象征着团圆与奔赴，演唱会是她与歌迷跨越山海、温暖相聚的盛大时刻。', '《礼物》巡演发布会舞美概念（转述）', 2026, 8);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-infinite', '巡演', 0);
INSERT INTO quote_tag (quote_id, tag, sort_no) VALUES ('q-infinite', '舞美', 1);
INSERT INTO quote_item (id, content, origin, quote_year, sort_no) VALUES ('q-chengfeng-intro', '今晚我把《一个人想着一个人》唱给你听。', '《乘风2026》初舞台前动态', 2026, 9);
